def analyze2(metric):
    def dist(A,B):
        if metric=='min': return min(abs(py-y)+abs(px-x) for py,px in A for y,x in B)
        if metric=='centroid':
            ca=(sum(y for y,x in A)/len(A),sum(x for y,x in A)/len(A))
            cb=(sum(y for y,x in B)/len(B),sum(x for y,x in B)/len(B))
            return math.dist(ca,cb)
        if metric=='corner':
            # corner of L = first cell
            ca=A[0]; return min(abs(ca[0]-y)+abs(ca[1]-x) for y,x in B)
    ok=True
    for idx,(gi,go) in enumerate([(p['input'],p['output']) for p in pairs]+[(demo1_in,demo1_out),(demo2,demo2_out)]):
        bg,objs=components(gi)
        changed=set((y,x) for y in range(len(gi)) for x in range(len(gi[0])) if gi[y][x]!=go[y][x])
        def isLprop(cl):
            s=set(cl); ys={y for y,x in cl}; xs={x for y,x in cl}
            for (cy,cx) in cl:
                vcol=sorted(y for y in ys if (y,cx) in s); hrow=sorted(x for x in xs if (cy,x) in s)
                if len(vcol)>=2 and len(hrow)>=2 and len(vcol)+len(hrow)-1==len(cl) and {(y,cx) for y in vcol}|{(cy,x) for x in hrow}==s:
                    if all(vcol[i+1]-vcol[i]==1 for i in range(len(vcol)-1)) and all(hrow[i+1]-hrow[i]==1 for i in range(len(hrow)-1)):
                        if (cy in (vcol[0],vcol[-1])) and (cx in (hrow[0],hrow[-1])): return True
            return False
        bigL=max((cl for c,cl in objs if isLprop(cl)),key=len)
        classes=defaultdict(list)
        for c,cl in objs: classes[skey(cl)].append((c,cl))
        cands=[(k,v) for k,v in classes.items() if len(v)==2 and len({c for c,_ in v})==2 and len(k)>1]
        # predicted: recolor member with larger dist
        pred=set()
        for k,v in cands:
            (c0,a),(c1,b)=v
            d0,d1=dist(bigL,a),dist(bigL,b)
            pred |= set(a if d0>d1 else b)
        exp=changed
        if pred!=exp:
            ok=False
            print(metric,'idx',idx,'MISMATCH pred',len(pred),'exp',len(exp))
    print(metric,'all ok' if ok else 'FAIL')
