def components8(g):
    from collections import deque
    H,W=len(g),len(g[0]); cnt=Counter(c for r in g for c in r); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; out=[]
    for y in range(H):
        for x in range(W):
            if g[y][x]!=bg and not seen[y][x]:
                q=deque([(y,x)]); seen[y][x]=True; cl=[]
                while q:
                    cy,cx=q.popleft(); cl.append((cy,cx))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=cy+dy,cx+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]!=bg:
                                seen[ny][nx]=True; q.append((ny,nx))
                out.append((g[y][x],sorted(cl)))
    return bg,out
