prog='''import sys
from collections import Counter, defaultdict

def components(g, bg=None):
    H, W = len(g), len(g[0])
    if bg is None:
        cnt = Counter(v for row in g for v in row)
        bg = cnt.most_common(1)[0][0]
    seen = [[False]*W for _ in range(H)]
    objs = []
    for y in range(H):
        for x in range(W):
            if seen[y][x] or g[y][x] == bg: continue
            col = g[y][x]; stack=[(y,x)]; seen[y][x]=True; cl=[]
            while stack:
                cy,cx = stack.pop(); cl.append((cy,cx))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx = cy+dy,cx+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==col:
                        seen[ny][nx]=True; stack.append((ny,nx))
            objs.append((col,cl))
    return bg, objs

def skey(cl):
    ys=[y for y,x in cl]; xs=[x for y,x in cl]
    return frozenset((y-min(ys),x-min(xs)) for y,x in cl)

def findLs(gi):
    bg,objs=components(gi); out=[]
    for c,cl in objs:
        s=set(cl); ys={y for y,x in cl}; xs={x for y,x in cl}
        for (cy,cx) in cl:
            vcol=sorted(y for y in ys if (y,cx) in s); hrow=sorted(x for x in xs if (cy,x) in s)
            if len(vcol)>=2 and len(hrow)>=2 and len(vcol)+len(hrow)-1==len(s) \
               and all(vcol[i+1]-vcol[i]==1 for i in range(len(vcol)-1)) \
               and all(hrow[j+1]-hrow[j]==1 for j in range(len(hrow)-1)) \
               and (cy in (vcol[0],vcol[-1])) and (cx in (hrow[0],hrow[-1])):
                out.append((c,cl))
    return out

def mind(Lset, cl):
    return min(abs(py-y)+abs(px-x) for py,px in Lset for y,x in cl)

def transform(grid):
    g=[row[:] for row in grid]
    LsL=findLs(g)
    if not LsL: return g
    L=max(LsL,key=lambda t:len(t[1]))
    Lset=set(L[1]); Lc=L[0]
    bg,objs=components(g)
    same=[cl for c,cl in objs if cl!=L[1] and len(cl)==len(L[1])]
    target=None
    if same:
        same.sort(key=lambda cl:-mind(Lset,cl))
        target=set(same[0])
    else:
        classes=defaultdict(list)
        for c,cl in objs: classes[skey(cl)].append((c,cl))
        cands=[]
        for k,v in classes.items():
            if len(v)!=2: continue
            ds=[mind(Lset,cl) for c,cl in v]
            if min(ds)==2: cands.append((len(v[0][1]),v,ds))
        if not cands: return g
        cands.sort(key=lambda t:-t[0])
        v,ds=cands[0][1],cands[0][2]
        far = v[0] if ds[0]>ds[1] else v[1]
        target=set(far[1])
    for y,x in target: g[y][x]=Lc
    return g'''
