        babove=any(y<corner[0] for y,x in b); bbelow=any(y>corner[0] for y,x in b)
        opp = -1 if vdir=='down' else 1  # opposite-vdir side sign
        def dL(cl2): return min(abs(y2-y)+abs(x2-x) for y2,x2 in Lcl for y,x in cl2)
        if (aabove and bbelow) or (abelow and bbelow==False and False): pass
        straddle = (aabove and bbelow) or (abelow and babove)
        if straddle:
            # candidate = member strictly on opposite-vdir side
            if opp<0:
                for c,cl2 in mem:
                    if all(y<corner[0] for y,x in cl2): cands.append((dL(cl2),c,cl2))
            else:
                for c,cl2 in mem:
