            bleft=any(x<corner[1] for y,x in b); bright=any(x>corner[1] for y,x in b)
            if (aleft and bright) or (aright and bleft):
                side=-1 if hdir=='left' else 1
                for c,cl2 in mem:
                    xs=[x for y,x in cl2]
                    if side<0 and all(x<corner[1] for x in xs): cands.append((dL(cl2),c,cl2))
                    if side>0 and all(x>corner[1] for x in xs): cands.append((dL(cl2),c,cl2))
    if not cands: return 'NOCAND'
    cands.sort(key=lambda t:t[0])
    c,cl2=cands[0][1],cands[0][2]
