    if not cands: return None
    if mode=='near': return min(cands,key=lambda cl: min(abs(y-ey)+abs(x-ex) for y,x in cl))
    if mode=='far': return max(cands,key=lambda cl: min(abs(y-ey)+abs(x-ex) for y,x in cl))
    if mode=='big': return max(cands,key=len)
